import{j as e}from"./jsx-runtime.ClP7wGfN.js";import{N as d}from"./Nav.sZqEGKhi.js";import{B as c,F as h}from"./Breadcrumbs.CwXZO9UN.js";import{r as u}from"./index.DK-fsZOb.js";import{R as t}from"./Reveal.B3f00t5K.js";import{M as p}from"./Magnetic.CKkyChOH.js";function m({items:a}){const[r,l]=u.useState(0);return e.jsx("div",{children:a.map((s,o)=>{const n=r===o;return e.jsxs("div",{className:`iv-faq ${n?"open":""}`,children:[e.jsx("button",{type:"button",className:"iv-faq-q","aria-expanded":n,onClick:()=>l(n?null:o),children:s.q}),e.jsx("div",{className:"iv-faq-a",children:s.a})]},s.q)})})}const i=[{label:"Working Together",sub:"Timelines, pricing, and how an engagement actually runs day to day.",items:[{q:"How long does a project usually take?",a:"Most full custom builds are delivered in 5–9 weeks depending on scope and the number of revisions. The $500 Launch package ships in 2–3 weeks. We give a fixed timeline at the kickoff call, not a vague range — and we hit it."},{q:"What does pricing typically look like?",a:"Most custom vape or smoke shop websites land between $4,500 and $14,000 depending on number of pages, custom photography, age-gated e-commerce, and identity work. The $500 Launch package is a fixed-price entry option for qualifying projects. We quote a firm number before we start — no hourly billing surprises."},{q:"How do payments work?",a:"Most projects are split 50% to begin and 50% on launch. Larger engagements may include milestone payments. We invoice via Stripe and accept ACH for US-based clients. Wire transfer available for international."},{q:"Can we start with the $500 offer?",a:"Yes. The $500 Launch package is available for qualifying vape and smoke shop projects with a clear brief and a single decision-maker on the client side. It&apos;s a great way to start working together — and many shops move into full custom engagements after launching with us."},{q:"How many revisions are included?",a:"Two full revision rounds per design phase. Additional rounds are billed at our hourly rate. In practice we rarely hit the cap — the discovery work up front means the first round is usually 80% of the way there."}]},{label:"Services",sub:"What we make, and what we leave to specialists.",items:[{q:"What kind of websites do you create?",a:"Sophisticated, conversion-focused websites for vape shops, smoke shops, and premium vape brands — with strong visual storytelling and refined interaction design. Age-gated commerce, editorial layouts, mobile-first builds, real performance."},{q:"Do you only work with vape and smoke shops?",a:"These are our primary focus because we deeply understand the visual, compliance, and operational needs of these industries — from age-gating to RAW outlet merchandising. We will consider adjacent premium lifestyle brands (CBD brands, glass studios, lifestyle e-commerce) on a case-by-case basis."},{q:"Do you also handle branding, packaging, and print?",a:"Yes. Logo, brand systems, labels, packaging, lookbooks, and in-store signage are part of the practice. We design full identities, not just websites — and the most successful engagements touch all of these surfaces together."},{q:"Do you do logo-only or rebrand-only projects?",a:"Occasionally, yes — typically as the foundation for a future website engagement. We don&apos;t take on identity work in isolation if there&apos;s no clear digital follow-up planned."},{q:"Do you offer SEO, content writing, or photography?",a:"Technical SEO foundation is included in every build. Long-form content writing and original photography are not in scope by default — we have partners we recommend and integrate seamlessly with their work."}]},{label:"Process & Practical",sub:"How we run a project, where we&apos;re based, and the working logistics.",items:[{q:"Where is the studio based, and do you work remotely?",a:"We&apos;re based in the American Midwest and work with clients nationwide. Most engagements run fully remote — kickoff and presentations over video, async feedback through shared documents and live design files. We travel for flagship engagements when it matters."},{q:"What does the design review process look like?",a:"We deliver concepts in Figma with annotated rationale. Reviews happen async through Figma comments and a live walkthrough call. We don&apos;t send PDFs — you see the actual responsive layouts as they&apos;ll behave in the browser."},{q:"Do you sign NDAs?",a:"Yes, mutual NDAs are standard before we share any project specifics. We can sign yours or use our boilerplate."},{q:"Can we see work-in-progress between milestones?",a:"Always. You&apos;ll have view access to the Figma file and the staging environment from day one. There are no surprise reveals — the work develops in the open."}]},{label:"Technical & Ownership",sub:"Hosting, CMS, code ownership, and what happens after launch.",items:[{q:"What CMS do you build on?",a:"Most builds ship on Next.js with a headless CMS layer (Sanity, Payload, or Contentful depending on the team running it). The $500 Launch package can ship as a static site without a CMS for the simplest cases."},{q:"Where does the site get hosted?",a:"We recommend and set up hosting on Vercel for Next.js sites — fast global delivery, automatic deploys, generous free tier. We can also deploy to any host you already use (Hostinger, AWS, etc.)."},{q:"Who owns the design files and the code?",a:"You do, in full. On launch, you receive the Figma source files, the Git repository, all editable image assets, and a written handoff document. There is no lock-in."},{q:"What happens after launch?",a:"We stay on as the team for the first month so nothing breaks under traffic. After that, we offer a monthly retainer for ongoing design + small features, or you can take everything in-house with full handoff. Most clients keep us on at a modest retainer for at least the first six months."},{q:"Can you maintain a site you didn&apos;t build?",a:"Generally no — we don&apos;t take on legacy maintenance. Exception: if you&apos;re bringing us in to do a full redesign of an existing site, we&apos;ll naturally inherit and migrate everything."}]}],g=i.flatMap(a=>a.items),f={"@context":"https://schema.org","@type":"FAQPage",mainEntity:g.map(a=>({"@type":"Question",name:a.q,acceptedAnswer:{"@type":"Answer",text:a.a}}))};function j(){return e.jsxs(e.Fragment,{children:[e.jsx(d,{}),e.jsx("main",{children:e.jsx("section",{className:"iv-section",style:{paddingTop:130},children:e.jsxs("div",{className:"iv-container-narrow",children:[e.jsx(c,{items:[{name:"Home",href:"/"},{name:"FAQ",href:"/faq"}]}),e.jsxs(t,{className:"iv-section-head",children:[e.jsx("div",{className:"iv-eyebrow",children:"Questions"}),e.jsxs("h1",{children:["Frequently ",e.jsx("em",{children:"Asked."})]}),e.jsxs("p",{style:{color:"#aaa",marginTop:14},children:["Honest answers about pricing, timeline, process, ownership, and everything else you might want to know before reaching out. If your question isn't here,"," ",e.jsx("a",{href:"/contact",style:{color:"var(--accent)",borderBottom:"1px solid currentColor"},children:"just ask"}),"."]})]}),i.map(a=>e.jsxs(t,{className:"iv-faq-category",children:[e.jsx("div",{className:"iv-faq-category-label",children:a.label}),e.jsx("div",{className:"iv-faq-category-sub",children:a.sub}),e.jsx(m,{items:a.items})]},a.label)),e.jsxs(t,{style:{marginTop:40,padding:"36px 32px",background:"var(--surface)",border:"1px solid var(--border)",borderRadius:12,textAlign:"center"},children:[e.jsx("div",{className:"iv-eyebrow",style:{justifyContent:"center"},children:"Still Curious"}),e.jsx("h3",{style:{fontFamily:"var(--font-display), serif",fontSize:"1.7rem",fontWeight:400,marginBottom:10,letterSpacing:"-0.01em"},children:"We answer every inquiry personally."}),e.jsx("p",{style:{color:"var(--muted)",marginBottom:24,fontSize:14.5},children:"Send a rough note and we'll reply within one business day."}),e.jsx(p,{children:e.jsx("a",{href:"/contact",className:"iv-nav-cta",children:"Send a Note"})})]})]})})}),e.jsx(h,{}),e.jsx("script",{type:"application/ld+json",dangerouslySetInnerHTML:{__html:JSON.stringify(f)}})]})}export{j as default};
